function sprite109(ctx,ctrans,frame,ratio,time){
	var clips = [];
	var frame_cnt = 1;
	frame = frame % frame_cnt;
	switch(frame){
		case 0:
			var oldctx = ctx;
			var fcanvas = createCanvas(canvas.width,canvas.height);			var fctx = fcanvas.getContext("2d");
			enhanceContext(fctx);
			fctx.applyTransforms(ctx._matrix);
			ctx = fctx;
			place("text108",canvas,ctx,[1.0,0.0,0.0,1.0,-4279.0,-2408.0],ctrans,1,0,0,time);
			fcanvas = Filters.bevel(fcanvas,fcanvas.getContext("2d"),5.0,5.0,1.0,Filters.OUTER,[255,255,51,1.0],[0,0,0,1.0],44,5.0,false,1);
			ctx = oldctx;
			var ms=ctx._matrix;
			ctx.setTransform(1,0,0,1,0,0);
			ctx.drawImage(fcanvas,0,0);
			ctx.applyTransforms(ms);
			break;
	}
}

